#include <windows.h>
#include <shlobj.h>
#include <shellapi.h>
#include <wrl/client.h>
#include <iostream>
#include <vector>
#include "shell/folder.hpp"
#include "core/unicode.hpp"
using Microsoft::WRL::ComPtr;
static void check(HRESULT hr){if(FAILED(hr))throw std::runtime_error("Shell HRESULT "+std::to_string(static_cast<unsigned>(hr)));}
static std::vector<PITEMID_CHILD> enumerate(IShellFolder*folder){
    std::vector<PITEMID_CHILD>items;ComPtr<IEnumIDList>e;check(folder->EnumObjects(nullptr,SHCONTF_FOLDERS|SHCONTF_NONFOLDERS,&e));PITEMID_CHILD item=nullptr;
    while(e->Next(1,&item,nullptr)==S_OK){STRRET name{};check(folder->GetDisplayNameOf(item,SHGDN_NORMAL,&name));if(name.uType==STRRET_WSTR){std::cout<<crackhood::utf8(name.pOleStr)<<'\n';CoTaskMemFree(name.pOleStr);}items.push_back(item);}return items;
}
static ComPtr<IShellFolder> bind(IShellFolder*folder,PCUIDLIST_RELATIVE item){ComPtr<IShellFolder>out;check(folder->BindToObject(item,nullptr,IID_PPV_ARGS(&out)));return out;}
int wmain(int argc,wchar_t**argv){try{check(CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED));ComPtr<IShellFolder>root;check(CoCreateInstance(crackhood::CLSID_Crackhood,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&root)));
    if(argc>1&&std::wstring(argv[1])==L"--view"){auto host=CreateWindowExW(0,L"STATIC",L"Crackhood hidden view test",WS_OVERLAPPEDWINDOW,0,0,800,600,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);if(!host)throw std::runtime_error("View host failed");ComPtr<IExplorerBrowser>browser;check(CoCreateInstance(CLSID_ExplorerBrowser,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&browser)));RECT bounds{0,0,800,600};FOLDERSETTINGS settings{FVM_DETAILS,FWF_AUTOARRANGE};check(browser->Initialize(host,&bounds,&settings));check(browser->SetOptions(EBO_NOTRAVELLOG|EBO_NOBORDER));PIDLIST_ABSOLUTE path=nullptr;check(SHParseDisplayName(L"::{20D04FE0-3AEA-1069-A2D8-08002B30309D}\\::{5B4B37D2-ED9F-4A50-8A76-8DFE13DA7318}",nullptr,&path,0,nullptr));check(browser->BrowseToIDList(path,SBSP_ABSOLUTE));CoTaskMemFree(path);auto deadline=GetTickCount64()+2000;while(GetTickCount64()<deadline){MSG message;while(PeekMessageW(&message,nullptr,0,0,PM_REMOVE)){TranslateMessage(&message);DispatchMessageW(&message);}Sleep(10);}ComPtr<IFolderView>view;check(browser->GetCurrentView(IID_PPV_ARGS(&view)));int count=0;check(view->ItemCount(SVGIO_ALLVIEW,&count));std::cout<<"Hosted Explorer view items: "<<count<<'\n';browser->Destroy();browser.Reset();DestroyWindow(host);if(!count)throw std::runtime_error("Hosted view has no profiles");return 0;}
    if(argc>1&&std::wstring(argv[1])==L"--thispc"){PIDLIST_ABSOLUTE pc=nullptr;check(SHGetSpecialFolderLocation(nullptr,CSIDL_DRIVES,&pc));ComPtr<IShellFolder>desktop,folder;check(SHGetDesktopFolder(&desktop));check(desktop->BindToObject(pc,nullptr,IID_PPV_ARGS(&folder)));for(auto extra:{0u,unsigned(SHCONTF_STORAGE),unsigned(SHCONTF_FASTITEMS),unsigned(SHCONTF_NAVIGATION_ENUM)}){std::cout<<"This PC extra flags: 0x"<<std::hex<<extra<<std::dec<<'\n';ComPtr<IEnumIDList>e;check(folder->EnumObjects(nullptr,static_cast<SHCONTF>(SHCONTF_FOLDERS|SHCONTF_NONFOLDERS|extra),&e));PITEMID_CHILD item=nullptr;while(e->Next(1,&item,nullptr)==S_OK){auto full=ILCombine(pc,item);PWSTR name=nullptr;if(SUCCEEDED(SHGetNameFromIDList(full,SIGDN_NORMALDISPLAY,&name))){std::cout<<crackhood::utf8(name)<<'\n';CoTaskMemFree(name);}CoTaskMemFree(full);CoTaskMemFree(item);}}CoTaskMemFree(pc);return 0;}
    PIDLIST_ABSOLUTE absolute=nullptr;check(SHParseDisplayName(L"::{20D04FE0-3AEA-1069-A2D8-08002B30309D}\\::{5B4B37D2-ED9F-4A50-8A76-8DFE13DA7318}",nullptr,&absolute,0,nullptr));ComPtr<IPersistFolder>persist;check(root.As(&persist));check(persist->Initialize(absolute));CoTaskMemFree(absolute);
    if(argc>1&&(std::wstring(argv[1])==L"--open"||std::wstring(argv[1])==L"--execute")){PIDLIST_ABSOLUTE path=nullptr;check(SHParseDisplayName(L"::{20D04FE0-3AEA-1069-A2D8-08002B30309D}\\::{5B4B37D2-ED9F-4A50-8A76-8DFE13DA7318}",nullptr,&path,0,nullptr));HRESULT hr;if(std::wstring(argv[1])==L"--execute"){SHELLEXECUTEINFOW info{sizeof(info)};info.fMask=SEE_MASK_IDLIST|SEE_MASK_NOASYNC|SEE_MASK_FLAG_NO_UI;info.lpVerb=L"open";info.lpIDList=path;info.nShow=SW_SHOWNORMAL;hr=ShellExecuteExW(&info)?S_OK:HRESULT_FROM_WIN32(GetLastError());}else hr=SHOpenFolderAndSelectItems(path,0,nullptr,0);CoTaskMemFree(path);std::cout<<"Shell open result: 0x"<<std::hex<<static_cast<unsigned>(hr)<<'\n';check(hr);return 0;}
    auto profiles=enumerate(root.Get());ComPtr<IShellFolder>console;for(auto p:profiles){SFGAOF flags=SFGAO_FOLDER;PCUITEMID_CHILD child=p;check(root->GetAttributesOf(1,&child,&flags));if(!console&&(flags&SFGAO_FOLDER))console=bind(root.Get(),p);CoTaskMemFree(p);}if(!console)throw std::runtime_error("No console profiles");
    auto wait=[](IShellFolder*f){for(unsigned attempt=0;attempt<60;++attempt){auto items=enumerate(f);bool ready=false;for(auto p:items){SFGAOF flags=SFGAO_FOLDER;PCUITEMID_CHILD child=p;check(f->GetAttributesOf(1,&child,&flags));if(flags&SFGAO_FOLDER)ready=true;}if(ready)return items;for(auto p:items)CoTaskMemFree(p);Sleep(100);}throw std::runtime_error("No live folders after 6 seconds");};
    auto drives=wait(console.Get());auto hdd=bind(console.Get(),drives[0]);for(auto p:drives)CoTaskMemFree(p);auto files=wait(hdd.Get());for(auto p:files)CoTaskMemFree(p);
    ComPtr<IShellView>view;check(hdd->CreateViewObject(nullptr,IID_PPV_ARGS(&view)));std::cout<<"Installed namespace, live browsing and standard view: PASS\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
